{
  "packet_id": "H6-T01-3",
  "claim_id": "C052",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C052.component",
    "value": "If unresolved contradictions undermine a disputed feature, that feature should no longer be treated as established.",
    "scope": "Conditional withdrawal of established status, beyond merely lowering confidence when a contradiction is encountered.",
    "provenance": {
      "refs": [
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P032 explicitly makes undermining unresolved contradictions a condition for withdrawing established treatment."
    }
  },
  "signal_basis": {
    "component_id": "C052.signal_basis",
    "value": "Comparison of sources concerning the same equipment, booking and handoff reveals contradictions that remain unresolved after reconciliation and undermine the disputed feature.",
    "scope": "Withdrawal applies when contradictions undermine the feature's evidential standing, not whenever any disagreement occurs.",
    "provenance": {
      "refs": [
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P012",
          "role": "SUPPORT"
        },
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the matched subject of comparison, reconciliation without forced agreement, and the qualifying condition that unresolved contradictions undermine the feature."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C052.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No additional empirical relation is required for this bounded withdrawal of established status."
    }
  },
  "rationale": "When unresolved contradictions undermine the evidence for a feature, continuing to treat it as established is unwarranted. The claim licenses withdrawal of that status without asserting that the feature is false.",
  "uncertainty": "The feature's truth may remain unresolved; that uncertainty is consistent with withdrawing established status.",
  "anomalies": []
}
